+use std::io::{self, BufRead, Write};
+
+pub fn process_lines<R, W, F>(reader: R, mut writer: W, transform: F) -> io::Result<usize>
+where
+    R: BufRead,
+    W: Write,
+    F: Fn(&str) -> String,
+{
+    let mut count = 0;
+    for line in reader.lines() {
+        let line = line?;
+        writeln!(writer, "{}", transform(&line))?;
+        count += 1;
+    }
+    Ok(count)
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+    use std::io::Cursor;
+
+    #[test]
+    fn test_process_lines_uppercase() {
+        let input = Cursor::new("hello\nworld\n");
+        let mut output = Vec::new();
+        let n = process_lines(input, &mut output, |l| l.to_uppercase()).unwrap();
+        assert_eq!(n, 2);
+        assert_eq!(output, b"HELLO\nWORLD\n");
+    }
+}

